1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Bookmark flow prototype</title>
7	  <style>
8	    :root { color-scheme: light; --ink:#17231d; --muted:#66736c; --line:#dfe6e1; --green:#176b47; --wash:#f4f7f4; }
9	    * { box-sizing: border-box; }
10	    body { margin:0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color:var(--ink); background:#fbfcfb; }
11	    .shell { min-height:100vh; display:grid; grid-template-columns:240px 1fr; }
12	    aside { padding:30px 22px; background:#eef3ef; border-right:1px solid var(--line); }
13	    .brand { display:flex; align-items:center; gap:10px; font-weight:760; font-size:19px; margin-bottom:38px; }
14	    .mark { width:30px; height:30px; display:grid; place-items:center; border-radius:9px; color:#fff; background:var(--green); }
15	    nav a { display:flex; gap:12px; align-items:center; padding:11px 12px; color:#536159; text-decoration:none; border-radius:9px; margin:5px 0; }
16	    nav a.active { background:#fff; color:var(--ink); font-weight:650; box-shadow:0 1px 2px #1c382520; }
17	    main { width:min(880px, calc(100vw - 290px)); margin:0 auto; padding:62px 0; }
18	    h1 { margin:0; font-family:Georgia, serif; font-size:42px; letter-spacing:-1.2px; }
19	    .lede { color:var(--muted); font-size:17px; margin:10px 0 34px; }
20	    .savebox { background:#fff; padding:18px; border:1px solid var(--line); border-radius:14px; box-shadow:0 10px 30px #223d2c0a; }
21	    .row { display:flex; gap:10px; }
22	    input { flex:1; font:inherit; padding:14px 15px; border:1px solid #cbd5ce; border-radius:9px; outline:none; }
23	    input:focus { border-color:var(--green); box-shadow:0 0 0 3px #176b4718; }
24	    button { font:inherit; font-weight:700; border:0; border-radius:9px; padding:0 20px; color:#fff; background:var(--green); cursor:pointer; }
25	    button:disabled { opacity:.45; cursor:not-allowed; }
26	    .status { min-height:20px; margin-top:10px; color:var(--muted); font-size:14px; }
27	    .preview { display:none; margin-top:14px; padding:14px; border-radius:10px; background:var(--wash); }
28	    .preview.show { display:block; }
29	    .preview strong { display:block; margin-bottom:5px; }
30	    .preview p { margin:0; color:var(--muted); line-height:1.45; }
31	    .section-head { display:flex; justify-content:space-between; align-items:center; margin-top:48px; }
32	    h2 { font-size:17px; margin:0; }
33	    .count { font-size:13px; color:var(--muted); }
34	    .empty { margin-top:14px; padding:58px 20px; text-align:center; color:var(--muted); border:1px dashed #cbd5ce; border-radius:13px; background:#fff; }
35	    .card { margin-top:14px; padding:19px 20px; background:#fff; border:1px solid var(--line); border-radius:12px; }
36	    .card a { color:var(--ink); font-weight:730; font-size:18px; text-decoration:none; }
37	    .card p { color:var(--muted); line-height:1.5; margin:8px 0; }
38	    .domain { color:var(--green); font-size:13px; }
39	    @media (max-width:720px) { .shell{grid-template-columns:1fr} aside{display:none} main{width:auto;padding:32px 20px} .row{flex-direction:column} button{height:48px} h1{font-size:34px} }
40	  </style>
41	</head>
42	<body>
43	  <div class="shell" data-harness-ready="true">
44	    <aside>
45	      <div class="brand"><span class="mark">⌑</span> Keepsake</div>
46	      <nav>
47	        <a class="active" href="#">▤ &nbsp;All bookmarks</a>
48	        <a href="#">◷ &nbsp;Read later</a>
49	        <a href="#"># &nbsp;Tags</a>
50	      </nav>
51	    </aside>
52	    <main>
53	      <h1>Your bookmarks</h1>
54	      <p class="lede">Save the useful corners of the web.</p>
55	      <section class="savebox" aria-label="Save a bookmark">
56	        <div class="row">
57	          <input id="url" aria-label="Web address" placeholder="Paste a web address…" autocomplete="off">
58	          <button id="save" disabled>Save bookmark</button>
59	        </div>
60	        <div id="status" class="status">Paste an address to get started.</div>
61	        <div id="preview" class="preview">
62	          <strong id="preview-title"></strong>
63	          <p id="preview-description"></p>
64	        </div>
65	      </section>
66	      <div class="section-head"><h2>All bookmarks</h2><span id="count" class="count">0 bookmarks</span></div>
67	      <div id="list"><div class="empty">Your saved links will appear here.</div></div>
68	    </main>
69	  </div>
70	  <script>
71	    const url = document.querySelector('#url');
72	    const save = document.querySelector('#save');
73	    const status = document.querySelector('#status');
74	    const preview = document.querySelector('#preview');
75	    const list = document.querySelector('#list');
76	    const count = document.querySelector('#count');
77	    let timer;
78	    let details = null;
79	    const known = {
80	      'developer.mozilla.org': ['CSS grid layout - CSS | MDN', 'CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.'],
81	      'www.nationalgeographic.com': ['National Geographic', 'Explore the world through science, history, nature, and culture.'],
82	      'en.wikipedia.org': ['Wikipedia, the free encyclopedia', 'The free encyclopedia that anyone can edit.']
83	    };
84	    url.addEventListener('input', () => {
85	      clearTimeout(timer); details=null; preview.classList.remove('show'); save.disabled=true;
86	      const value=url.value.trim();
87	      if (!value) { status.textContent='Paste an address to get started.'; return; }
88	      status.textContent='Getting page details…';
89	      timer=setTimeout(() => {
90	        try {
91	          const parsed=new URL(value);
92	          const fallback=[parsed.hostname.replace(/^www\./,''), 'Saved from '+parsed.hostname+'.'];
93	          details=known[parsed.hostname] || fallback;
94	          document.querySelector('#preview-title').textContent=details[0];
95	          document.querySelector('#preview-description').textContent=details[1];
96	          preview.classList.add('show'); status.textContent='Page details found.'; save.disabled=false;
97	        } catch { status.textContent='That doesn’t look like a complete web address.'; }
98	      }, 550);
99	    });
100	    save.addEventListener('click', () => {
101	      if (!details) return;
102	      const parsed=new URL(url.value.trim());
103	      list.innerHTML=`<article class="card"><a href="${parsed.href}" target="_blank" rel="noreferrer">${details[0]}</a><p>${details[1]}</p><span class="domain">${parsed.hostname}</span></article>`;
104	      count.textContent='1 bookmark'; status.textContent='Bookmark saved.'; preview.classList.remove('show');
105	      url.value=''; save.disabled=true; details=null;
106	    });
107	  </script>
108	</body>
109	</html>
