const exampleBookmarks = [
  { title:'CSS grid layout - CSS | MDN', url:'https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_grid_layout', description:'A complete guide to two-dimensional layouts with rows and columns.', site:'developer.mozilla.org', tags:['web design','reference'] },
  { title:'The Marginalian', url:'https://www.themarginalian.org/', description:'Long-form reflections on books, art, philosophy, and what makes a meaningful life.', site:'themarginalian.org', tags:['reading','essays'] },
  { title:'A guide to better sourdough bread', url:'https://example.com/sourdough', description:'Practical notes on starters, fermentation, shaping, and baking.', site:'example.com', tags:['cooking','read later'] },
  { title:'Inclusive Components', url:'https://inclusive-components.design/', description:'Accessible interface patterns, with practical examples and thoughtful explanations.', site:'inclusive-components.design', tags:['accessibility','web design'] }
];
function renderLaterChoice(variant, marked=false) {
  const controls={
    '1': `<button class="later-control icon-later ${marked ? 'marked' : ''}" aria-label="${marked ? 'Remove from' : 'Add to'} read later">${marked ? '★' : '☆'}</button>`,
    '2': `<button class="later-control label-later ${marked ? 'marked' : ''}">${marked ? '✓ In read later' : '+ Read later'}</button>`,
    '3': `<button class="later-control menu-later" aria-label="Bookmark actions">•••</button>`
  };
  list.innerHTML=`<article class="card later-card">${controls[variant]}<a href="#">The Marginalian</a><p>Long-form reflections on books, art, philosophy, and what makes a meaningful life.</p><span class="domain">themarginalian.org</span><div class="saved-tags"><button class="chip">reading</button><button class="chip">essays</button></div>${marked ? '<div class="later-feedback">Added to Read later</div>' : ''}</article>`;
  count.textContent='1 bookmark';
}
function renderExamples(items) {
  list.innerHTML=items.length ? items.map(item => `<article class="card"><a href="${item.url}" target="_blank" rel="noreferrer">${item.title}</a><p>${item.description}</p><span class="domain">${item.site}</span><div class="saved-tags">${item.tags.map(tag => `<button class="chip" data-tag="${tag}">${tag}</button>`).join('')}</div></article>`).join('') : '<div class="empty">No bookmarks match your search.</div>';
  count.textContent=`${items.length} bookmark${items.length === 1 ? '' : 's'}`;
}
const prototypeView=new URLSearchParams(location.search).get('view');
if (prototypeView === 'search') {
  document.querySelector('.savebox').style.display='none';
  document.querySelector('#searchbox').style.display='block';
  document.querySelector('.lede').textContent='Find anything you saved.';
  renderExamples(exampleBookmarks);
  search.addEventListener('input', () => {
    document.querySelector('#filter-note').classList.remove('show');
    const term=search.value.trim().toLowerCase();
    renderExamples(exampleBookmarks.filter(item => [item.title, item.description, ...item.tags].some(value => value.toLowerCase().includes(term))));
  });

