  });
  document.querySelector('#clear-filter').addEventListener('click', () => {
    document.querySelector('#filter-note').classList.remove('show'); renderExamples(exampleBookmarks);
  });
} else if (prototypeView === 'readlater') {
  document.querySelector('.savebox').style.display='none';
  document.querySelector('#later-variants').style.display='flex';
  document.querySelector('.lede').textContent='Keep something close for when you have time.';
  renderLaterChoice('1');
  document.querySelectorAll('.later-variant').forEach(button => button.addEventListener('click', () => {
    document.querySelectorAll('.later-variant').forEach(item => item.classList.toggle('active', item === button));
    renderLaterChoice(button.dataset.later);
  }));
  list.addEventListener('click', event => {
    const control=event.target.closest('.later-control');
    if (!control) return;
    const variant=document.querySelector('.later-variant.active').dataset.later;
    if (variant === '3') {
      if (control.classList.contains('label-later')) { renderLaterChoice(variant, true); return; }
      control.outerHTML='<button class="later-control label-later">Add to Read later</button>';
      return;
    }
    renderLaterChoice(variant, true);
  });
} else if (prototypeView === 'laterlist') {
  document.querySelector('.savebox').style.display='none';
  document.querySelector('h1').textContent='Read later';
  document.querySelector('.lede').textContent='The links you set aside for later.';
  document.querySelector('.section-head h2').textContent='Saved for later';
  document.querySelectorAll('nav a').forEach(item => item.classList.remove('active'));
  document.querySelector('#later-link').classList.add('active');
  list.innerHTML='<article class="card later-card"><button class="later-control icon-later marked" aria-label="Remove from read later">★</button><a href="https://www.themarginalian.org/" target="_blank" rel="noreferrer">The Marginalian</a><p>Long-form reflections on books, art, philosophy, and what makes a meaningful life.</p><span class="domain">themarginalian.org</span><div class="saved-tags"><button class="chip">reading</button><button class="chip">essays</button></div></article>';
  count.textContent='1 bookmark';
} else if (prototypeView === 'manage') {
  document.querySelector('.savebox').style.display='none';
  document.querySelector('#manage-variants').style.display='flex';
  document.querySelector('.lede').textContent='Keep saved details accurate and useful.';
  renderManageChoice('1');
  document.querySelectorAll('.manage-variant').forEach(button => button.addEventListener('click', () => {
    document.querySelectorAll('.manage-variant').forEach(item => item.classList.toggle('active', item === button));
    renderManageChoice(button.dataset.manage);
  }));
  list.addEventListener('click', event => {
    const variant=document.querySelector('.manage-variant.active').dataset.manage;
    if (event.target.closest('[data-menu]')) { renderManageChoice(variant, true); return; }
    if (event.target.closest('[data-edit]')) { renderEditForm(); return; }
    if (event.target.closest('[data-cancel-edit]')) { renderManageChoice(variant); return; }
    if (event.target.closest('[data-save-edit]')) {
      const title=document.querySelector('#edit-title').value;
      renderManageChoice(variant); document.querySelector('.later-card > a').textContent=title;
      const note=document.createElement('div'); note.className='later-feedback'; note.textContent='Bookmark updated'; document.querySelector('.later-card').append(note);
    }
  });
}
url.addEventListener('input', () => {
  clearTimeout(timer); details=null; preview.classList.remove('show'); save.disabled=true;
  const value=url.value.trim();
  if (!value) { status.textContent='Paste an address to get started.'; return; }
  status.textContent='Getting page details…';
  timer=setTimeout(() => {
    try {
      const parsed=new URL(value);
      const fallback=[parsed.hostname.replace(/^www\./,''), 'Saved from '+parsed.hostname+'.'];
      details=known[parsed.hostname] || fallback;
      document.querySelector('#preview-title').textContent=details[0];
      document.querySelector('#preview-description').textContent=details[1];

